pageCss:
.hf-code{background:var(--row-alt);border:1px solid #c8d2e2;border-left:3px solid var(--luna-44);padding:8px 10px;margin:0 0 12px;overflow-x:auto;font-size:var(--text-xs);line-height:1.5}
.hf-code code{white-space:pre}
.hf-demo{border:1px solid var(--slate-73);background:var(--row-alt);margin:14px 0 16px;box-shadow:inset 1px 1px 0 #fff}
.hf-bar{background:var(--surface-desktop);border-bottom:1px solid #c8d2e2;padding:5px 8px;display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}
.hf-filters{display:inline-flex;gap:4px;flex-wrap:wrap}
.hf-count{font-size:var(--text-micro);color:var(--slate-52)}
.hf-scroll{overflow-x:auto;background:#fff}
.hf-table{border-collapse:collapse;font-size:var(--text-micro);width:100%;min-width:560px}
.hf-table th{text-align:left;background:var(--surface-desktop);border:1px solid #c8d2e2;padding:4px 7px;font-family:var(--font-caption);color:var(--slate-38);position:sticky;top:0}
.hf-table td{border:1px solid var(--slate-90);padding:4px 7px;vertical-align:top;line-height:1.45}
.hf-table tbody tr:nth-child(odd) td{background:var(--paper-cool)}
.hf-table code{font-size:var(--text-2xs);font-family:var(--font-mono)}
.hf-here td{background:#fdf6e0 !important;box-shadow:inset 3px 0 0 #e0a72c}
.hf-tag{display:inline-block;font-size:var(--text-3xs);padding:0 5px;border-radius:8px;background:var(--slate-92);color:#3d4d68;white-space:nowrap}
.hf-static{margin:0 0 12px}
.hf-ok{color:#1c6b32;font-weight:bold}
.hf-no{color:#a3261a;font-weight:bold}
.hf-case{padding:10px 12px;background:#fff;font-size:var(--text-xs);line-height:1.55}
.hf-case h3{font-family:var(--font-caption);color:var(--luna-44);font-size:var(--text-body);margin:0 0 5px}
.hf-case pre{background:var(--row-alt);border:1px solid #c8d2e2;padding:7px 9px;margin:0 0 8px;overflow-x:auto;font-size:var(--text-micro)}
.hf-case pre code{white-space:pre;font-family:var(--font-mono)}
.hf-case table{border-collapse:collapse;font-size:var(--text-micro);width:100%;margin:0 0 6px}
.hf-case th{text-align:left;background:var(--surface-desktop);border:1px solid #c8d2e2;padding:3px 7px;color:var(--slate-38)}
.hf-case td{border:1px solid var(--slate-90);padding:3px 7px;vertical-align:top}
.hf-cost{font-size:var(--text-micro);color:var(--slate-52);margin:0}
@media(max-width:620px){.hf-table{min-width:460px}}
.hf-rad{position:absolute;opacity:0;width:1px;height:1px;pointer-events:none}
.hf-filters label{font:inherit;font-size:var(--text-2xs);padding:2px 8px;border:1px solid #a9b4c6;background:linear-gradient(180deg,#fff,var(--surface-desktop));border-radius:3px;cursor:pointer;color:var(--slate-38);user-select:none}
.hf-rad:focus-visible+label{outline:1px dotted var(--ink,#000);outline-offset:-3px}
.hf-rad:checked+label{background:linear-gradient(180deg,#cfe0fb,#a8c6f4);border-color:#5f86c8;color:#12305e;font-weight:bold}
.hf-c{display:none}
.hf-inv:has(#hf-f-all:checked) .hf-c[data-f="all"]{display:inline}
.hf-inv:has(#hf-f-here:checked) .hf-c[data-f="here"]{display:inline}
.hf-inv:has(#hf-f-release:checked) .hf-c[data-f="release"]{display:inline}
.hf-inv:has(#hf-f-config:checked) .hf-c[data-f="config"]{display:inline}
.hf-inv:has(#hf-f-containers:checked) .hf-c[data-f="containers"]{display:inline}
.hf-inv:has(#hf-f-setup:checked) .hf-c[data-f="setup"]{display:inline}
.hf-inv:has(#hf-f-legacy:checked) .hf-c[data-f="legacy"]{display:inline}
.hf-inv:has(#hf-f-types:checked) .hf-c[data-f="types"]{display:inline}
.hf-inv:has(#hf-f-here:checked) .hf-table tbody tr:not(.hf-here){display:none}
.hf-inv:has(#hf-f-release:checked) .hf-table tbody tr:not([data-g="release"]){display:none}
.hf-inv:has(#hf-f-config:checked) .hf-table tbody tr:not([data-g="config"]){display:none}
.hf-inv:has(#hf-f-containers:checked) .hf-table tbody tr:not([data-g="containers"]){display:none}
.hf-inv:has(#hf-f-setup:checked) .hf-table tbody tr:not([data-g="setup"]){display:none}
.hf-inv:has(#hf-f-legacy:checked) .hf-table tbody tr:not([data-g="legacy"]){display:none}
.hf-inv:has(#hf-f-types:checked) .hf-table tbody tr:not([data-g="types"]){display:none}
/* Hidden rows still count for :nth-child, so a filter stripes among the rows it keeps (the script used to rebuild the tbody). */
.hf-inv:has(#hf-f-here:checked) .hf-table tbody tr:nth-child(odd) td,.hf-inv:has(#hf-f-release:checked) .hf-table tbody tr:nth-child(odd) td,.hf-inv:has(#hf-f-config:checked) .hf-table tbody tr:nth-child(odd) td,.hf-inv:has(#hf-f-containers:checked) .hf-table tbody tr:nth-child(odd) td,.hf-inv:has(#hf-f-setup:checked) .hf-table tbody tr:nth-child(odd) td,.hf-inv:has(#hf-f-legacy:checked) .hf-table tbody tr:nth-child(odd) td,.hf-inv:has(#hf-f-types:checked) .hf-table tbody tr:nth-child(odd) td{background:none}
.hf-inv:has(#hf-f-here:checked) .hf-table tbody tr:nth-child(odd of .hf-here) td,.hf-inv:has(#hf-f-release:checked) .hf-table tbody tr:nth-child(odd of [data-g="release"]) td,.hf-inv:has(#hf-f-config:checked) .hf-table tbody tr:nth-child(odd of [data-g="config"]) td,.hf-inv:has(#hf-f-containers:checked) .hf-table tbody tr:nth-child(odd of [data-g="containers"]) td,.hf-inv:has(#hf-f-setup:checked) .hf-table tbody tr:nth-child(odd of [data-g="setup"]) td,.hf-inv:has(#hf-f-legacy:checked) .hf-table tbody tr:nth-child(odd of [data-g="legacy"]) td,.hf-inv:has(#hf-f-types:checked) .hf-table tbody tr:nth-child(odd of [data-g="types"]) td{background:var(--paper-cool)}
.hf-cases-demo .hf-case{display:none}
.hf-cases-demo:has(#hf-c-ignored:checked) .hf-case[data-c="ignored"]{display:block}
.hf-cases-demo:has(#hf-c-closed:checked) .hf-case[data-c="closed"]{display:block}
.hf-cases-demo:has(#hf-c-undocumented:checked) .hf-case[data-c="undocumented"]{display:block}
.hf-cases-demo:has(#hf-c-routing:checked) .hf-case[data-c="routing"]{display:block}
